# -*- coding: utf-8 -*-
"""中文蘑菇安全问答对(作者撰写,事实依据 kb.py 与公开资料,见 data/qa_zh/NOTICE.md)

QA_ZH 为手工撰写的中文问答对,共 150 条,类别分布:
毒性 40 / 急救 25 / 区分 30 / 食用 25 / 环境 20 / 烹饪 10。

铁律:毒蘑菇绝不说成可食用;涉及医疗处置的答案一律以
“请立即就医/联系中毒控制中心,以医生意见为准”收尾。
"""
QA_ZH = [
    # ================================================================= #
    # 毒性(40 条):症状、毒素、潜伏期
    # ================================================================= #
    dict(question="毒鹅膏中毒的典型症状是什么?", answer="毒鹅膏(Amanita phalloides)含鹅膏毒肽,潜伏期6到24小时。初期剧烈呕吐、腹痛和水样腹泻,随后进入看似好转的假愈期,接着发展为急性肝功能衰竭,可危及生命。出现这类症状应立即就医并保留蘑菇样本。", category="毒性"),
    dict(question="为什么毒鹅膏中毒的人会先好转一阵子?", answer="这是毒鹅膏(Amanita phalloides)中毒的假愈期:鹅膏毒肽已进入肝脏破坏肝细胞,但胃肠道症状暂时平息,让人误以为没事了。之后黄疸、肝衰竭接踵而来,所以即使好转也必须立刻就医,以医生意见为准。", category="毒性"),
    dict(question="毒鹅膏里的毒素是怎么害人的?", answer="毒鹅膏(Amanita phalloides)的主要毒素是α-鹅膏毒肽,它抑制RNA聚合酶Ⅱ,阻断肝细胞合成蛋白质,导致肝细胞大量坏死。它耐热耐干燥,煮熟晒干都破坏不了,因此只能靠准确鉴别来避免误食。", category="毒性"),
    dict(question="白毒伞吃了会怎样?", answer="白毒伞(Amanita virosa / A. bisporigera)和毒鹅膏一样含鹅膏毒肽,中毒症状几乎相同:进食6到24小时后呕吐、腹泻,接着假愈,最后肝肾功能衰竭。它是世界上最毒的蘑菇之一,误食后请立即就医,以医生意见为准。", category="毒性"),
    dict(question="毒蝇伞中毒是什么感觉?", answer="毒蝇伞(Amanita muscaria)含鹅膏蕈氨酸和蝇蕈醇,进食后30分钟到2小时出现恶心、嗜睡、意识混乱、幻觉和醉酒般的步态不稳。虽然极少致死,但过程非常难受,误食应尽快就医并联系中毒控制中心。", category="毒性"),
    dict(question="豹斑鹅膏中毒和毒蝇伞有什么不一样?", answer="豹斑鹅膏(Amanita pantherina)含同样的毒素但比例不同,症状更不稳定也更凶险:进食后1到3小时内出现意识混乱、躁动、幻觉、肌肉抽搐,严重时会昏迷。切勿因毒蝇伞毒性较轻就小看它。", category="毒性"),
    dict(question="大青褶伞为什么是北美最常见的中毒元凶?", answer="大青褶伞(Chlorophyllum molybdites)喜欢长在草坪和花园里,外表又像可食的高大环柄菇,极易被误采。它含胃肠刺激毒素,吃后30分钟到3小时便剧烈呕吐、腹泻,是北美蘑菇中毒最常见的原因。", category="毒性"),
    dict(question="大青褶伞中毒的潜伏期有多长?", answer="大青褶伞(Chlorophyllum molybdites)的潜伏期约30分钟到3小时,属于发作较快的胃肠刺激型中毒。症状以恶心、剧烈呕吐和腹泻为主,一般不会致命但非常难受,儿童老人容易脱水,应及时就医。", category="毒性"),
    dict(question="墨汁鬼伞和酒一起吃会怎样?", answer="墨汁鬼伞(Coprinopsis atramentaria)含鬼伞素,会阻断酒精分解,喝酒后出现脸红、出汗、恶心、心悸和头痛,像吃了戒酒药一样,且酒后数天内都可能发作。误食后请立即就医,以医生意见为准。", category="毒性"),
    dict(question="秋生盔孢伞有多毒?", answer="秋生盔孢伞(Galerina marginata)个头虽小,却和毒鹅膏一样含鹅膏毒肽,属于致命级。它成群长在朽木上,极易被误认为可食的木生蘑菇,进食6到24小时后呕吐腹泻,随后肝衰竭。", category="毒性"),
    dict(question="致命环柄菇为什么不能碰?", answer="致命环柄菇(Lepiota brunneoincarnata)这类小环柄菇同样含鹅膏毒肽,是“小个子里的杀手”。潜伏6到24小时后出现呕吐、腹泻,继而肝衰竭。它们常混在草坪草丛中,与可食小菇难分,所以小个白色孢子印的环柄菇一律别吃。", category="毒性"),
    dict(question="丝膜菌中毒为什么最可怕?", answer="致命丝膜菌(Cortinarius rubellus / C. orellanus)含奥来毒素,专门攻击肾脏,潜伏期长达2天到3周,初期只是类似感冒的症状,等发现时往往已肾衰竭,需要透析甚至换肾。潜伏期之长居所有蘑菇中毒之首。", category="毒性"),
    dict(question="吃了鹿花菌会有什么症状?", answer="鹿花菌(Gyromitra esculenta)含鹿花菌素,在体内分解为有毒的甲基肼,潜伏5到10小时后呕吐、腹泻,严重者肝损伤、抽搐甚至昏迷,有致死记录。它和羊肚菌春天同期出现,务必学会区分。", category="毒性"),
    dict(question="毒火珊瑚菌有多危险?", answer="毒火珊瑚菌(Podostroma cornu-damae)含单端孢霉烯类毒素,抑制蛋白质合成,是已知最毒的蘑菇之一。进食后数小时到数天出现恶心呕吐、白细胞血小板下降、皮肤脱皮和脱发,日本韩国都有致死案例。", category="毒性"),
    dict(question="黄斑菇吃了会怎样?", answer="黄斑菇(Agaricus xanthodermus)含酚类刺激物,吃后几小时内恶心、呕吐、腹泻,通常不致命但很难受。它的特征是菌盖菌柄受伤处立刻变黄,并散发药水一样的酚味,记住这两点就不会认错。", category="毒性"),
    dict(question="毒粉褶菌中毒有什么表现?", answer="毒粉褶菌(Entoloma sinuatum)含胃肠刺激毒素,进食后30分钟到2小时出现剧烈恶心、呕吐和腹泻。它菌褶成熟后呈鲑鱼粉色,孢子印是粉红色,这是与可食白蘑类区分的关键。", category="毒性"),
    dict(question="毒杯伞的毒蕈碱中毒有什么症状?", answer="毒杯伞(Clitocybe dealbata / C. rivulosa)含毒蕈碱,刺激副交感神经,进食后15分钟到2小时大量出汗、流泪、流涎、视物模糊、呕吐腹泻、心跳变慢,严重时可致死。草地上小个白色漏斗状蘑菇务必远离。", category="毒性"),
    dict(question="毒红菇为什么叫“致吐菇”?", answer="毒红菇(Russula emetica)名字直译就是“致吐者”。它含胃肠刺激物,吃后不久剧烈恶心呕吐,辛辣的菌肉是警告信号。红菇家族里凡菌肉辛辣的通常有毒,温和的才可食。", category="毒性"),
    dict(question="橙黄蜡伞吃了会怎样?", answer="橙黄蜡伞(Omphalotus olearius)又称杰克灯,含伊鲁丁类毒素,进食后30分钟到3小时出现剧烈绞痛、呕吐和腹泻。它常被误当鸡油菌,鉴别要点是它长在木头上、菌褶锋利且夜间会发光。", category="毒性"),
    dict(question="簇生黄韧伞中毒是什么情况?", answer="簇生黄韧伞(Hypholoma fasciculare)含韧伞素等毒素,吃后几小时内恶心、呕吐、腹泻。它的菌褶呈黄绿色,味道极苦,大多数人咬一口就吐掉,因此严重中毒不多见,但仍应完全避开。", category="毒性"),
    dict(question="黄硬皮马勃能当马勃吃吗?", answer="不能。黄硬皮马勃(Scleroderma citrinum)切开后内部是紫黑色,而可食马勃内部纯白。它含胃肠刺激毒素,误食后几小时恶心呕吐腹泻。记住铁律:马勃状蘑菇一定要切开看内部再决定。", category="毒性"),
    dict(question="鹿花菌和羊肚菌的毒性差在哪?", answer="羊肚菌(Morchella esculenta)做熟后可食,而鹿花菌(Gyromitra esculenta)含鹿花菌素,分解出类似火箭燃料的甲基肼,可致肝损伤甚至死亡。两者都在春天出现,但羊肚菌菌盖是蜂窝状凹坑,鹿花菌是脑状皱褶,这是生死之别。", category="毒性"),
    dict(question="黄拟口蘑为什么从美味变成禁食?", answer="黄拟口蘑(Tricholoma equestre)曾被视为美味,法国却出现连续食用后肌肉剧痛、无力,发展为横纹肌溶解、肾衰竭甚至死亡的案例。这提醒我们:“祖辈常吃”并不能证明安全,毒素机制至今未明。", category="毒性"),
    dict(question="天使之翼对谁特别危险?", answer="天使之翼(Pleurocybella porrigens)本身毒性不明,但日本发生多起肾病患者食用后急性脑病死亡的案例。它雪白纤薄,长在针叶树朽木上,与平菇相似。肾病患者应完全避免,其他人也建议不吃。", category="毒性"),
    dict(question="鹅膏毒肽煮熟后还有毒吗?", answer="有。鹅膏毒肽和奥来毒素都耐高温,煮、炸、炖、晒干都破坏不了;鹿花菌素虽可挥发但处理风险极大。所以“煮熟就安全”的说法对最致命的蘑菇完全不成立,只能靠鉴别。", category="毒性"),
    dict(question="哪些毒素是可以靠加热破坏的?", answer="羊肚菌(Morchella esculenta)、蜜环菌(Armillaria mellea)里的溶血素和部分刺激物怕热,彻底做熟就没问题;鹿花菌素可挥发。但鹅膏毒肽、奥来毒素、毒蕈碱都耐热。所以必须分蘑菇种类谈烹饪,不能一概而论。", category="毒性"),
    dict(question="吃毒蘑菇后症状出现越晚越危险吗?", answer="大致如此。发作越快多是胃肠刺激物,难受但不致命;而鹅膏毒肽潜伏6到24小时,奥来毒素潜伏2天到3周,越晚越说明毒素在攻击肝肾。延迟发作的蘑菇恰恰最凶险。", category="毒性"),
    dict(question="世界上致死人数最多的毒蘑菇是哪个?", answer="是毒鹅膏(Amanita phalloides)。它含鹅膏毒肽,占了全球蘑菇致死案例的大多数,而且外观朴素、与多种可食菇相似,在欧亚北美都有分布。误食后必须争分夺秒就医,以医生意见为准。", category="毒性"),
    dict(question="颜色越鲜艳的蘑菇越毒吗?", answer="不对。金色鸡油菌(Cantharellus cibarius)、橙红色的橙盖鹅膏都鲜艳可口,而致命的毒鹅膏是橄榄灰色、白毒伞通体纯白。鲜艳与否不能判断毒性,唯一的可靠办法是系统鉴别。", category="毒性"),
    dict(question="银针、大蒜能试出蘑菇有没有毒吗?", answer="不能。银针变黑、大蒜变色的说法没有任何科学依据,鹅膏毒肽不与银反应。这类偏方会给人虚假安全感,延误就医。识别毒蘑菇只能靠形态、孢子和生境等特征。", category="毒性"),
    dict(question="毒蘑菇都长在阴暗潮湿的深山里吗?", answer="不是。大青褶伞(Chlorophyllum molybdites)、黄斑菇就长在小区草坪和公园里,毒鹅膏常出现在公园橡树下。越是日常环境越容易麻痹大意,草坪里的蘑菇和深山里的蘑菇要同样警惕。", category="毒性"),
    dict(question="毒蘑菇是不是都有怪味或苦味?", answer="不一定。毒鹅膏、白毒伞的味道并不特别,甚至有人觉得不错;反之苦牛肝菌(Tylopilus felleus)虽苦到毁掉一锅菜却不含毒素。靠味道判断毒性既不科学又危险,请以形态鉴别为准。", category="毒性"),
    dict(question="小动物吃过的蘑菇人就能吃吗?", answer="不能。昆虫、啮齿动物和鸟类的代谢系统与人不同,它们吃没事的蘑菇人吃了可能致命。用动物试吃判断毒性的做法不可靠,人也绝不能去试吃陌生蘑菇。", category="毒性"),
    dict(question="鹅膏毒肽中毒会经历哪几个阶段?", answer="经典的三阶段:先是进食6到24小时后剧烈呕吐腹泻的胃肠炎期;接着是看似痊愈的假愈期;最后是肝肾功能衰竭期。三个阶段环环相扣,任何阶段都必须在医院处理。", category="毒性"),
    dict(question="毒蝇伞干燥后毒素会变吗?", answer="会。毒蝇伞(Amanita muscaria)里的鹅膏蕈氨酸在干燥或加热过程中会部分转化为蝇蕈醇,后者精神作用更强,所以晒干的毒蝇伞毒性表现可能不同。无论鲜品干品,毒蝇伞都不可食用。", category="毒性"),
    dict(question="豹斑鹅膏的豹斑综合征是什么?", answer="指进食豹斑鹅膏(Amanita pantherina)后1到3小时内出现的意识混乱、兴奋躁动、幻觉、肌肉抽搐,严重者昏迷,与毒蝇伞症状类似但更不稳定。这是鹅膏蕈氨酸和蝇蕈醇引起的中枢神经中毒表现。", category="毒性"),
    dict(question="长在木头上的蘑菇是不是更安全?", answer="不是。平菇(Pleurotus ostreatus)、蜜环菌可食,但同是木生的秋生盔孢伞(Galerina marginata)、簇生黄韧伞都含毒素,前者还致命。木生菇同样要查菌褶颜色、菌环和寄主树种,不能因为长在木头上就放松警惕。", category="毒性"),
    dict(question="胃肠刺激型蘑菇中毒一般有多严重?", answer="这是全世界最常见的中毒类型,由大青褶伞、橙黄蜡伞、硫磺簇等引起,表现为30分钟到3小时内呕吐腹泻腹痛。虽通常自愈,但脱水、儿童老人体弱者仍需就医处理。", category="毒性"),
    dict(question="误把苦牛肝菌当美味牛肝菌吃了会中毒吗?", answer="不会中毒,但会毁掉整顿饭。苦牛肝菌(Tylopilus felleus)极苦,一片就能让整锅菜无法下咽。它的菌孔粉褐色、味道极苦,和美味牛肝菌(Boletus edulis)的白色菌孔、清甜菌肉完全不同。", category="毒性"),
    dict(question="毒鹅膏的幼体和草菇有多像?", answer="确实像:草菇(Volvariella volvacea)也有菌托,幼菇都被包裹在蛋状外膜里。但草菇是粉色孢子印、栽培在稻草上且没有菌环;毒鹅膏是白色孢子印、有菌环、长在树下。拿不准就切开看孢子印。", category="毒性"),

    # ================================================================= #
    # 急救(25 条):误食后怎么办、就医、保留样本、催吐与否
    # ================================================================= #
    dict(question="误食毒蘑菇后第一时间该做什么?", answer="立即联系当地中毒控制中心或拨打急救电话,同时保存所有吃剩的蘑菇和呕吐物,不要等出现症状。最危险的毒素发作慢,越早干预越好,请以医生的意见为准。", category="急救"),
    dict(question="误食毒蘑菇后要不要自己催吐?", answer="不要自行催吐,除非医生明确指示。催吐可能造成误吸、损伤食道,而且对已吸收的鹅膏毒肽毫无作用。正确做法是尽快就医,把专业处理交给医生。", category="急救"),
    dict(question="为什么要保留误食的蘑菇样本?", answer="蘑菇种类决定治疗方案和预后判断。把吃剩的完整蘑菇用纸袋或纸巾包好冷藏,别洗别切,连同呕吐物一起带给医生,可以大大帮助鉴定毒种,争取宝贵时间。", category="急救"),
    dict(question="吃完蘑菇好几个小时都没症状,还要去医院吗?", answer="要去。鹅膏毒肽潜伏6到24小时,奥来毒素甚至长达数周,没症状不代表安全。等到呕吐腹泻出现时肝损伤可能已经开始,所以应立即就医并联系中毒控制中心。", category="急救"),
    dict(question="孩子误食了野生蘑菇怎么办?", answer="先把孩子嘴里剩余的蘑菇取出来,留好样本,立刻联系中毒控制中心或就医,不要等孩子出现症状。千万别自行催吐,也别用任何偏方,处理方式以医生意见为准。", category="急救"),
    dict(question="去医院时应该告诉医生什么?", answer="尽量说清进食时间、吃了多少、怎么烹饪的、吃了哪几种蘑菇、什么时间开始不舒服、有什么症状,并把蘑菇样本和呕吐物带上。信息越全,医生判断越准。", category="急救"),
    dict(question="误食蘑菇后的呕吐物要不要留着?", answer="要留。呕吐物里可能有未消化的蘑菇碎片,是鉴定的重要材料。用干净容器装好冷藏,和蘑菇样本一起带给医生,能帮助确定毒素种类,请以医生意见为准。", category="急救"),
    dict(question="采蘑菇时拍照有什么用?", answer="非常有用。照片记录了蘑菇的原始形态、生长位置和生境,鉴定价值很高。万一误食,照片配合实物样本能让医生和专家更快锁定毒种,争取救治时间。", category="急救"),
    dict(question="网上说的牛奶、醋、绿豆能解蘑菇毒吗?", answer="不能,这些都是没有依据的偏方。鹅膏毒肽等毒素无法被这些食物中和,乱灌东西反而可能引起误吸、加重病情。唯一正确的做法是尽快就医并联系中毒控制中心。", category="急救"),
    dict(question="吃了毒鹅膏但感觉好多了,还要继续治疗吗?", answer="必须继续。毒鹅膏中毒的假愈期会让人误以为康复,此时肝细胞正在被破坏。擅自中断治疗可能错过挽救时机,请严格遵从医嘱,以医生的意见为准。", category="急救"),
    dict(question="误食蘑菇后可以在家观察一晚上吗?", answer="不建议。胃肠刺激型虽多可自愈,但鹅膏毒肽、奥来毒素的延迟发作意味着等到症状明显时伤害已经造成。怀疑中毒就应去医院评估,别拿肝脏肾脏赌一夜。", category="急救"),
    dict(question="猫狗误食了蘑菇怎么办?", answer="立即联系兽医或宠物毒物中心,带上蘑菇样本。宠物可能会啃食草坪里的蘑菇,常见有毒种包括大青褶伞(Chlorophyllum molybdites)等。不要自行给宠物催吐,处理方式请遵从兽医意见。", category="急救"),
    dict(question="在中国误食毒蘑菇该打哪个电话?", answer="可以拨打120急救电话,说明是疑似蘑菇中毒并请求转达中毒控制中心;部分地区可直接联系当地疾控或急诊科。就医时带上样本,一切处置以医生意见为准。", category="急救"),
    dict(question="去医院路上能做什么?", answer="带好蘑菇样本和呕吐物,不要催吐,不要自行服药,保持患者呼吸道通畅,防止呕吐物误吸。如果患者意识不清,让其侧卧。到医院后把进食细节完整告诉医生。", category="急救"),
    dict(question="活性炭能自己买来吃吗?", answer="不要自行使用。活性炭确实可能在早期由医生用来吸附部分毒素,但时机、剂量都要专业判断,自行服用可能延误治疗或引起并发症。请交给急诊医生处理。", category="急救"),
    dict(question="鹅膏毒肽中毒能治好吗?", answer="能,但靠的是抢时间。早期就诊可采取洗胃、活性炭、补液和保肝等支持治疗,严重肝衰竭时可能需要肝移植。越早治疗成功率越高,请立即就医并遵从医嘱。", category="急救"),
    dict(question="吃了没煮熟的羊肚菌怎么办?", answer="没煮熟的羊肚菌(Morchella esculenta)可能引起恶心、呕吐和腹部绞痛。如果症状明显或吃得多,建议联系中毒控制中心评估,一般对症处理后缓解,具体处置以医生意见为准。", category="急救"),
    dict(question="喝酒后吃了墨汁鬼伞出现脸红心悸怎么办?", answer="这是鬼伞素阻断酒精代谢引起的中毒反应,应立即停止饮酒、尽快就医,并如实告诉医生蘑菇种类和饮酒时间。反应虽多可自行缓解,但仍需医生评估处理。", category="急救"),
    dict(question="误食蘑菇后多久内就医效果最好?", answer="越早越好,理想是在进食后几小时内。鹅膏毒肽进入血液后仍可被吸附和处理,拖到肝衰竭阶段就非常被动。怀疑中毒就别犹豫,立即联系中毒控制中心就医。", category="急救"),
    dict(question="症状很轻的蘑菇中毒也要就医吗?", answer="建议就医。一是部分毒素发作延迟,轻症可能是暴风雨前的平静;二是呕吐腹泻本身可致脱水,老人儿童更需评估。请由医生判断是否需要留院观察。", category="急救"),
    dict(question="不确定自己吃的是不是毒蘑菇怎么办?", answer="按疑似中毒处理:保留剩余样本,立即联系中毒控制中心说明情况,由专业人员评估风险。宁可虚惊一场,也不要错过救治窗口,一切以医生意见为准。", category="急救"),
    dict(question="毒蘑菇中毒急救的总原则是什么?", answer="四句话:留样本、快就医、别催吐、不信偏方。样本和照片帮助鉴定,就医交给专业处理,延迟毒素最危险所以千万别等,处置一律以医生意见为准。", category="急救"),
    dict(question="误食蘑菇后还能喝水吗?", answer="可以少量喝清水,但不要大量灌水催吐,也不要用牛奶盐水之类。如果患者意识不清则不要喂任何东西以防误吸。静脉补液交给医生,现场不要自行处理。", category="急救"),
    dict(question="老人或孕妇误食蘑菇该怎么办?", answer="立即就医,同时保留样本。老人肝肾功能较弱、孕妇涉及胎儿安全,风险更高,任何处置都应优先由急诊和专科医生评估,切勿在家自行观察或使用偏方。", category="急救"),
    dict(question="蘑菇中毒的“黄金窗口”是什么?", answer="指进食后尽早到院的治疗时段,此时毒素尚在胃肠道或血中,可通过洗胃、活性炭等措施减少吸收。鹅膏毒肽等延迟毒素尤其需要抢在肝损伤前处理,请立即就医。", category="急救"),

    # ================================================================= #
    # 区分(30 条):相似种鉴别、孢子印、菌盖菌褶菌托菌环特征
    # ================================================================= #
    dict(question="鸡油菌和橙黄蜡伞怎么区分?", answer="看菌褶和生长位置:鸡油菌(Cantharellus cibarius)的“菌褶”是钝的叉状棱纹,长在地上与树共生,有淡淡杏香;橙黄蜡伞(Omphalotus olearius)有锋利真菌褶,丛生在木头和树桩上。两点一对照就分清了。", category="区分"),
    dict(question="羊肚菌和鹿花菌怎么区分?", answer="羊肚菌(Morchella esculenta)菌盖是蜂窝状凹坑、与菌柄完全连生,整体中空;鹿花菌(Gyromitra esculenta)菌盖是脑状皱褶、内部有腔室。春天同时出现,看菌盖形状就能一锤定音,鹿花菌绝对不要吃。", category="区分"),
    dict(question="美味牛肝菌和苦牛肝菌怎么区分?", answer="美味牛肝菌(Boletus edulis)菌孔幼时白色、老时黄绿色,菌柄顶部有白色细网纹,菌肉清甜;苦牛肝菌(Tylopilus felleus)菌孔粉褐色,菌柄网纹粗糙,菌肉极苦。咬一小口尝苦味是行家的标准动作。", category="区分"),
    dict(question="大青褶伞和高大环柄菇怎么区分?", answer="最可靠的是孢子印:大青褶伞(Chlorophyllum molybdites)的孢子印是绿色,高大环柄菇(Macrolepiota procera)是白色。高大环柄菇菌柄有蛇皮纹和可移动双菌环,大青褶伞菌柄基部球状。草坪上的大伞务必先做孢子印。", category="区分"),
    dict(question="孢子印怎么做?", answer="把菌盖切下,菌褶朝下平放在纸上,一半白纸一半黑纸,盖上碗防气流,等几小时到过夜。孢子落下的颜色白、粉、褐、黑或绿,是鉴别相似种的关键证据。", category="区分"),
    dict(question="菌托是什么?为什么说它危险?", answer="菌托是菌柄基部杯状的囊,是包裹幼菇外膜的残留,也是鹅膏属的标志。毒鹅膏(Amanita phalloides)、白毒伞都有菌托,而鹅膏属里有世上最毒的蘑菇,见到菌托就该高度警惕。", category="区分"),
    dict(question="有菌环的蘑菇就能放心吃吗?", answer="不能。菌环只是内菌幕残留,毒鹅膏、白毒伞都有菌环,而香菇(Lentinula edodes)、双孢蘑菇也有菌环。菌环只是记录特征之一,既不证明安全也不证明有毒,必须综合鉴定。", category="区分"),
    dict(question="白毒伞和菜场的双孢蘑菇怎么区分?", answer="双孢蘑菇(Agaricus bisporus)菌褶幼时粉红、老时巧克力色,没有菌托;白毒伞(Amanita virosa / A. bisporigera)菌褶始终纯白,菌柄有菌环且基部有杯状菌托。看菌褶颜色和有没有菌托,一眼就能分开。", category="区分"),
    dict(question="白毒伞和草菇怎么区分?", answer="草菇(Volvariella volvacea)菌褶成熟后粉红色、孢子印粉色,栽培在稻草上;白毒伞(Amanita virosa / A. bisporigera)菌褶和孢子印纯白,长在树下或苔藓林地。虽然都有菌托,但孢子印颜色和生境完全不同。", category="区分"),
    dict(question="秋生盔孢伞和蜜环菌怎么区分?", answer="看菌褶和孢子印:秋生盔孢伞(Galerina marginata)菌褶锈褐色,孢子印锈色;蜜环菌(Armillaria mellea)菌褶乳白色,孢子印白色。盔孢伞生于针叶树朽木,蜜环菌丛生树基部且有菌环,锈色孢子印是死线。", category="区分"),
    dict(question="秋生盔孢伞和金针菇怎么区分?", answer="野生金针菇(Flammulina velutipes)菌褶乳白色、菌柄深色天鹅绒状,常寒冬长在阔叶朽木上;秋生盔孢伞(Galerina marginata)菌褶锈褐色、菌柄光滑有易碎菌环,长在针叶树朽木上。菌褶颜色立刻见分晓。", category="区分"),
    dict(question="毒红菇和可食红菇怎么区分?", answer="红菇家族的标准测试是咬一小点菌肉:辛辣刺激的是毒红菇(Russula emetica)一类,温和无味的多可食。毒红菇菌盖鲜红、表皮易剥,吃后剧烈呕吐。记住辣=危险,温和=可考虑。", category="区分"),
    dict(question="墨汁鬼伞和毛头鬼伞怎么区分?", answer="毛头鬼伞(Coprinus comatus)高大,白色圆柱状菌盖覆满鳞片,菌柄有小菌环,多长在路边草地;墨汁鬼伞(Coprinopsis atramentaria)灰色钟形、表面光滑,无鳞片和菌环,丛生树桩旁。毛头鬼伞嫩时可食,墨汁鬼伞与酒相克。", category="区分"),
    dict(question="松乳菇和绒白乳菇怎么区分?", answer="切断菌肉看乳汁:松乳菇(Lactarius deliciosus)流出胡萝卜色的橙汁,长在松树下;绒白乳菇(Lactarius torminosus)流出白色乳汁、菌盖边缘卷曲有绒毛,长在桦树下。绒白乳菇生吃会剧烈呕吐,务必看乳汁颜色。", category="区分"),
    dict(question="齿菌和珊瑚菌怎么区分?", answer="齿菌属的菌盖下面是柔软的刺,像刺猬背,如猴头菇(Hericium erinaceus);珊瑚菌(Ramaria spp.)是向上分叉的树枝状,没有菌盖也没有刺。齿菌几乎无危险相似种,珊瑚菌则有些种有毒。", category="区分"),
    dict(question="马勃和黄硬皮马勃怎么区分?", answer="切开看内部:可食的幼马勃内部纯白坚实;黄硬皮马勃(Scleroderma citrinum)内部紫黑或黄褐,外皮厚硬有疣。任何马勃状蘑菇都必须纵切检查,内部不是纯白一律不吃。", category="区分"),
    dict(question="马勃和鹅膏的“蛋”怎么区分?", answer="纵切看结构:马勃内部是纯白均匀的菌肉,没有形状;鹅膏幼菇内部能看见清晰的菌盖、菌褶和菌柄雏形,切开像小蘑菇。内部有结构的绝对不是马勃,而是致命鹅膏。", category="区分"),
    dict(question="假鸡油菌和鸡油菌怎么区分?", answer="假鸡油菌(Hygrophoropsis aurantiaca)菌褶薄而真、颜色深橙、分叉明显,菌肉软而脆,长在针叶林地面;真鸡油菌是钝的叉状棱,菌肉坚实有杏香。看菌褶是“棱”还是“片”就分清了。", category="区分"),
    dict(question="毒蝇伞和橙盖鹅膏怎么区分?", answer="看菌褶和菌环颜色:毒蝇伞(Amanita muscaria)菌褶和菌环纯白,菌盖红底白疣;橙盖鹅膏(Amanita caesarea)菌褶、菌环和菌柄都是金黄色,是罗马时代的宫廷美食。两者混淆后果严重,新手别碰红伞。", category="区分"),
    dict(question="豹斑鹅膏和变色鹅膏怎么区分?", answer="变色鹅膏(Amanita rubescens)的菌肉、菌褶受伤处会慢慢变成酒红色,这是它可食(须做熟)的标志;豹斑鹅膏(Amanita pantherina)受伤不变红,且含鹅膏蕈氨酸有毒。捏伤处看是否变红是最快的鉴别法。", category="区分"),
    dict(question="为什么新手被要求完全避开白色鹅膏?", answer="因为白毒伞等白色鹅膏全含鹅膏毒肽,而它们和可食的灰鹅膏(Amanita vaginata)、草菇外表相似。灰鹅膏虽无环可辨,但认错代价是生命,所以建议新手一律不碰白色鹅膏。", category="区分"),
    dict(question="小褐菇为什么让人谈之色变?", answer="小褐菇指那些褐色小型伞菌,种类上千、特征细微,其中秋生盔孢伞(Galerina marginata)、致命环柄菇都含鹅膏毒肽。专家都要靠显微镜或DNA鉴别,普通采菇人根本分不清,直接避开最安全。", category="区分"),
    dict(question="菌盖边缘的条纹状沟纹有什么用?", answer="条纹是菌褶透过菌盖边缘的痕迹,常见于灰鹅膏等鹅膏属,也见于小皮伞等。它可以作为辅助特征,但绝不能单独用来判断安全性,必须结合菌托、菌环和孢子印。", category="区分"),
    dict(question="菌柄基部膨大像球茎说明什么?", answer="球状基部常见于鹅膏属,往往伴随菌托残留,提示这可能是致命种。看到球茎加菌环加白菌褶的组合,就要按最危险的情况处理,直接放弃采集。", category="区分"),
    dict(question="毒鹅膏的幼体和草菇怎么分?", answer="毒鹅膏(Amanita phalloides)幼菇有菌环、孢子印白色,长在树下;草菇(Volvariella volvacea)没有菌环、孢子印粉红色,栽培于稻草上。两者都有菌托所以最易混,牢记“有环没环+孢子印颜色”两步法。", category="区分"),
    dict(question="网柄牛肝菌和美味牛肝菌怎么区分?", answer="网柄牛肝菌(Boletus reticulatus)的白色网纹覆盖菌柄下半部甚至基部,菌盖浅褐到黄褐;美味牛肝菌(Boletus edulis)的网纹只在菌柄近顶部。两者都可食,但都要排除粉孔、苦味的苦牛肝菌类。", category="区分"),
    dict(question="黄斑菇怎么一眼认出来?", answer="用手搓菌盖、切开菌柄基部,如果立刻出现亮黄色变色,并闻到药水般的酚味,就是黄斑菇(Agaricus xanthodermus)。可食的白蘑菇受伤不变黄、无酚味。这个“黄变测试”简单又可靠。", category="区分"),
    dict(question="毒粉褶菌有什么识别特征?", answer="毒粉褶菌(Entoloma sinuatum)菌褶成熟后变成鲑鱼粉红色,孢子印粉红,菌盖浅灰褐色、边缘波状内卷,常长在草地林缘。孢子印呈粉红色的伞菌要格外警惕,毒粉褶菌是其中的代表。", category="区分"),
    dict(question="变绿红菇和绿盖鹅膏怎么区分?", answer="变绿红菇(Russula virescens)菌盖龟裂成小块状拼图,菌柄无环无菌托;绿盖鹅膏菌盖光滑、有菌环和菌托。变绿红菇是美味,绿盖鹅膏近缘种多含毒,看菌盖裂不裂是关键。", category="区分"),
    dict(question="孢子印颜色能帮我们排除哪些危险?", answer="白色孢子印提示鹅膏属和部分环柄菇,要查菌托菌环;锈褐色孢子印要警惕秋生盔孢伞(Galerina marginata);粉红色对应毒粉褶菌;绿色孢子印就是大青褶伞(Chlorophyllum molybdites),直接判死刑。孢子印是快捷安检。", category="区分"),

    # ================================================================= #
    # 食用(25 条):哪些能吃、如何安全食用、栽培蘑菇、第一口少量
    # ================================================================= #
    dict(question="超市里卖的蘑菇安全吗?", answer="安全。双孢蘑菇(Agaricus bisporus)、香菇、平菇、金针菇等栽培菇由菌种在灭菌基质上培育,没有野生相似种的混淆风险,是零鉴定风险的食物,放心购买和食用。", category="食用"),
    dict(question="平菇能生吃吗?", answer="不建议生吃。平菇(Pleurotus ostreatus)要彻底做熟,口感更好也更安全。市面上栽培平菇虽无毒性,但生吃可能引起肠胃不适,而且它和有毒的天使之翼相似,野生平菇更要仔细鉴别。", category="食用"),
    dict(question="香菇能生吃吗?", answer="不建议。生吃或未煮熟的香菇(Lentinula edodes)可能引起香菇皮炎,一种瘙痒的鞭打样皮疹,敏感人群尤其明显。彻底煮熟即可避免,香菇是世界上最常见的栽培食用菌之一。", category="食用"),
    dict(question="鸡油菌怎么做最好吃?", answer="鸡油菌(Cantharellus cibarius)用黄油大火快煎,加盐和胡椒,让它先出水再收汁,杏子般的香气最浓。它肉质紧实,配鸡蛋、奶油或意面都很经典,是欧洲最受追捧的野生菌之一。", category="食用"),
    dict(question="羊肚菌能生吃吗?", answer="绝对不能生吃。生羊肚菌(Morchella esculenta)含溶血素类物质,会恶心、呕吐、绞痛。必须彻底煮熟,煎炒或炖汤皆可。还要先确认是真羊肚菌而非含毒的鹿花菌,鉴别错误比没煮熟更可怕。", category="食用"),
    dict(question="美味牛肝菌怎么吃?", answer="切片用黄油煎、烤或炖汤都很出色,也可切片晒干存起来,泡发水是高汤精华。美味牛肝菌(Boletus edulis)菌孔幼时白色、老时黄绿,菌肉清甜,千万别和粉孔苦味的苦牛肝菌搞混。", category="食用"),
    dict(question="松茸怎么吃?", answer="松茸(Tricholoma matsutake)最经典是炭火烤或切片生食,独有的松木辛香浓郁。它是松树根部的共生菌,秋季产于东亚,价格昂贵。吃之前务必确认菌褶白色、菌柄粗壮有环的特征。", category="食用"),
    dict(question="猴头菇怎么吃?", answer="猴头菇(Hericium erinaceus)炖汤、清炒或素菜仿海鲜都合适,肉质如蟹肉般一丝丝的。它长在活阔叶树的伤口上,形态独一无二没有危险相似种,是适合新手的木生食用菌。", category="食用"),
    dict(question="灰树花怎么吃?", answer="灰树花(Grifola frondosa)又称舞茸,丛生在老栎树基部,菌盖层层叠叠像羽毛。炖汤、干煸、油炸皆宜,香气浓郁。它没有致命相似种,是秋季值得寻找的木生食用菌。", category="食用"),
    dict(question="黑木耳泡发要注意什么?", answer="用凉水泡发并尽快食用,泡发超过一天且发黏、有酸味的木耳(Auricularia auricula-judae)可能被细菌污染产生毒素,引发食物中毒。木耳本身安全,风险在泡发环节,吃多少泡多少最稳妥。", category="食用"),
    dict(question="银耳怎么处理?", answer="银耳(Tremella fuciformis)凉水泡发后去蒂撕小朵,炖冰糖雪梨就是经典甜汤。它胶质丰富、口感软糯,是安全的栽培食用菌。注意泡发后当天吃完,别久存变质。", category="食用"),
    dict(question="草菇怎么吃才对?", answer="草菇(Volvariella volvacea)做熟后食用,是亚洲常见栽培菌。但它有菌托,和致命毒鹅膏的幼体很像,野外采的“草菇”绝不能吃,只有确认是栽培来源的才安全。", category="食用"),
    dict(question="第一次吃某种野生蘑菇该怎么试?", answer="取少量(一两朵)、单独烹饪、单独食用,别混在其他菜里,记录食用时间。吃完等24小时观察反应,无不适再考虑第二次。新种类别一次多吃,也别给家人试。", category="食用"),
    dict(question="新手适合先从哪些野生菌入手?", answer="相对安全的是特征鲜明、无致命相似种的:齿菌(Hydnum repandum)的刺猬状菌刺、鸡油菌的叉状棱纹、大马勃切开纯白。但每个都要按图谱逐一核对,最好有老手带路。", category="食用"),
    dict(question="一次能同时试好几种新蘑菇吗?", answer="不要。一次只试一种,才能把不适反应准确归因到具体种类。同时吃几种,出了问题医生都不知道该查谁,鉴别和急救都会陷入混乱。", category="食用"),
    dict(question="新蘑菇能给老人和孩子吃吗?", answer="别给。老人肝肾功能较弱,儿童代谢系统未成熟,同样的毒素反应更重。新种类先由成年人少量试吃确认无恙,再考虑是否分享给家人。", category="食用"),
    dict(question="栽培蘑菇和野生蘑菇的风险差在哪?", answer="栽培蘑菇从菌种到采收全程可控,不存在相似种混入,风险为零;野生蘑菇必须逐朵鉴定,一旦认错可能致命。想安全享受蘑菇,栽培菌是零门槛的选择。", category="食用"),
    dict(question="松乳菇怎么吃?", answer="松乳菇(Lactarius deliciosus)切片煎烤、盐渍或油浸都合适,是南欧的平民美味。它橙色的乳汁是鉴别铁证。吃前刮净菌盖、确认乳汁橙色、长在松树下,就不用担心和毒乳菇混淆。", category="食用"),
    dict(question="橙盖鹅膏能吃吗?", answer="能,橙盖鹅膏(Amanita caesarea)是罗马时代就受推崇的珍馐。但前提是确认菌褶、菌环、菌柄都是金黄色,且菌托完整;毒蝇伞是白菌褶白菌环。认不准就别碰,橙盖鹅膏不是新手练手对象。", category="食用"),
    dict(question="毛头鬼伞怎么吃?", answer="趁毛头鬼伞(Coprinus comatus)菌盖还没变黑发墨时采摘,当天尽快做熟,口感鲜嫩。它和含鬼伞素的墨汁鬼伞是不同种,但为避免风险,吃毛头鬼伞前后最好也别饮酒。", category="食用"),
    dict(question="毒蝇伞能吃吗?", answer="绝对不能。毒蝇伞(Amanita muscaria)含鹅膏蕈氨酸和蝇蕈醇,会致幻觉、昏迷,虽然死亡案例少但中毒极痛苦。民间传说和文艺作品里的形象不能当食用依据,请一律远离。", category="食用"),
    dict(question="蘑菇有营养吗?", answer="有。蘑菇低热量低脂肪,含蛋白质、膳食纤维、B族维生素、硒和钾,紫外线照射后还能合成维生素D2。是健康的日常食材,但营养再好也不能替代鉴别。", category="食用"),
    dict(question="路边摊和网购的野生蘑菇能买吗?", answer="不建议买任何来源不明的野生蘑菇。摊贩混入相似毒种、网购无法溯源的情况屡见不鲜,出了事连样本都难找。要吃就吃栽培菌,或自己严格鉴别采摘。", category="食用"),
    dict(question="自己在家种蘑菇安全吗?", answer="安全,这是零风险的吃菇方式。买平菇(Pleurotus ostreatus)、香菇、大球盖菇等正规菌包,按说明保湿通风即可出菇。因为菌种已知、基质可控,完全不存在野外鉴定的风险。", category="食用"),
    dict(question="哪些牛肝菌可以放心吃?", answer="遵守牛肝菌安全三原则:菌孔不是红色或橙色的、切面不会快速变深蓝、菌肉不苦,满足这三点的大多数牛肝菌可食。反之如恶魔牛肝菌(Boletus satanas)红孔有毒、苦牛肝菌极苦,一律放弃。", category="食用"),

    # ================================================================= #
    # 环境(20 条):生长环境、季节、共生树木
    # ================================================================= #
    dict(question="毒鹅膏一般长在什么地方?", answer="毒鹅膏(Amanita phalloides)是栎树、山毛榉、栗树等阔叶树的共生菌,夏末到秋季出现在树下,公园和路边绿化带也不少见。它已从欧洲扩散到北美、东亚,越是常见环境越要警惕。", category="环境"),
    dict(question="羊肚菌什么时候、在哪里采?", answer="羊肚菌(Morchella esculenta)是春季菌,四月前后出现在果园、白蜡树林、河漫滩和火烧迹地等扰动过的土地上。它们出菇时间短、和鹿花菌同期,采前务必确认蜂窝状菌盖。", category="环境"),
    dict(question="鸡油菌喜欢什么样的环境?", answer="鸡油菌(Cantharellus cibarius)与栎、山毛榉、桦树和针叶树共生,长在苔藓覆盖的林地上,夏末到深秋雨后成片出现。它永远长在地上,若发现“鸡油菌”长在木头上,那多半是毒蘑菇。", category="环境"),
    dict(question="松茸在什么环境里能找到?", answer="松茸(Tricholoma matsutake)与松树共生,长在干燥、排水良好的松林里,秋季出菇,东亚和北美都有分布。它对土壤要求苛刻,产量连年下降,这也是它价格昂贵的原因之一。", category="环境"),
    dict(question="松乳菇和什么树长在一起?", answer="松乳菇(Lactarius deliciosus)几乎只出现在松树下,尤其松树人工林里,秋季成片生长。它的共生对象是辨认线索:松树下橙色乳汁的乳菇可食,桦树下的白汁乳菇则有毒。", category="环境"),
    dict(question="美味牛肝菌和什么树共生?", answer="美味牛肝菌(Boletus edulis)与栎、山毛榉、桦树、云杉、松树都能形成共生关系,夏秋两季出现在老树附近。它偏爱林下湿润处,常和鸡油菌、齿菌出现在同一片林子。", category="环境"),
    dict(question="平菇长在哪里?", answer="平菇(Pleurotus ostreatus)长在枯死或濒死的阔叶树上,尤其山毛榉和杨树,成串层叠生长,温带地区秋到春都有。它是著名的木腐菌,也是世界上栽培量最大的食用菌之一。", category="环境"),
    dict(question="野生香菇长在什么树上?", answer="香菇(Lentinula edodes)原产东亚,野生时生长在枯死的硬木上,尤其壳斗科的青冈等树木。现在全球栽培主要用硬木段木或木屑菌包,秋冬季出菇,是亚洲最传统的食用菌。", category="环境"),
    dict(question="大青褶伞一般长在哪儿?", answer="大青褶伞(Chlorophyllum molybdites)最爱草坪、花园、牧场和路边,常在草地上围成仙女环成片出现,夏秋季最多。它把毒蘑菇带进了居民区,是城市草坪上最需要认识的中毒元凶。", category="环境"),
    dict(question="墨汁鬼伞在哪里最常见?", answer="墨汁鬼伞(Coprinopsis atramentaria)丛生在树桩基部、草坪、路边和腐殖质丰富的土地上,春到秋季雨后成群出现。它喜欢被扰动过的土壤,城市和乡村都能见到,是常见而非罕见。", category="环境"),
    dict(question="毒蝇伞和什么树长在一起?", answer="毒蝇伞(Amanita muscaria)与桦树、松树、云杉共生,尤其喜欢桦树,公园和林缘都常见。夏末到深秋出菇,红底白疣的样子辨识度极高,但褪色后要和其它红鹅膏仔细区分。", category="环境"),
    dict(question="猴头菇长在什么树上?", answer="猴头菇(Hericium erinaceus)长在活阔叶树的伤口或死木上,尤其栎树和山毛榉,夏末到秋季悬挂在树干上,像一团白色狮鬃。它专挑大树伤口寄生,在森林里不算常见。", category="环境"),
    dict(question="木耳一般长在哪里?", answer="木耳(Auricularia auricula-judae)长在接骨木、白蜡等阔叶树的枯枝上,形状像耳朵,雨后迅速膨胀。它全球温带都有分布,是亚洲餐桌上最常见的胶质菌,干品泡发后食用。", category="环境"),
    dict(question="冬虫夏草生长在什么环境?", answer="冬虫夏草(Ophiocordyceps sinensis)生活在青藏高原海拔三千米以上的高寒草甸,寄生于蝙蝠蛾幼虫体内,春季从虫尸上长出子座。它是世界上最贵的真菌,采集是高原地区的重要收入来源。", category="环境"),
    dict(question="松露长在哪里?", answer="松露(Tuber spp.)完全长在地下,深度5到20厘米,与栎树、榛树根系共生,偏爱钙质土壤,冬季成熟。采挖要靠受过训练的狗或猪嗅出气味,这也解释了它的天价。", category="环境"),
    dict(question="灵芝和云芝长在什么地方?", answer="灵芝(Ganoderma lucidum)长在阔叶树基部或倒木上,以栎树和枫树常见,夏秋季出现,漆亮的外表像上了光油;云芝(Trametes versicolor)则长在枯木和树桩上,全年可见,扇形菌盖上有一圈圈彩色环纹。", category="环境"),
    dict(question="蜜环菌对森林是益虫还是害虫?", answer="蜜环菌(Armillaria mellea)是寄生病原菌,它会侵入活树根系,让大片树木枯死,是森林里著名的“杀手”。它的黑色根状菌索能在土壤里蔓延很远,秋季在树基部丛生出蜜色蘑菇。", category="环境"),
    dict(question="野生金针菇什么时候出现?", answer="野生金针菇(Flammulina velutipes)在晚秋到早春的严寒期出现,常顶着霜冻长在阔叶朽木上,橘褐色的小伞配上黑褐色天鹅绒状菌柄。它和致命的秋生盔孢伞同期同境,必须看菌褶颜色。", category="环境"),
    dict(question="为什么下过雨蘑菇就冒出来?", answer="蘑菇菌丝在土壤和木头里常年潜伏,遇雨后的高湿度和温度骤降就会大量形成子实体,秋季第一场透雨后的“蘑菇潮”最壮观。但同一片林子可食与有毒常常并存。", category="环境"),
    dict(question="灰树花长在什么地方?", answer="灰树花(Grifola frondosa)丛生在老栎树的根部,秋季出现,一丛可重达数公斤,灰褐色菌盖层层叠叠像母鸡羽毛。它和硫磺菌都是栎树根部的常客,采前都要核对寄主是阔叶树。", category="环境"),

    # ================================================================= #
    # 烹饪(10 条):清洗、做熟、储存、干燥
    # ================================================================= #
    dict(question="蘑菇到底要不要用水洗?", answer="尽量别泡洗。栽培蘑菇用软刷或干布擦掉泥土即可,泡水会让菌肉吸水变烂、风味流失。确实脏的可以快速冲一下立即沥干,野生蘑菇则用刷子逐朵清理。", category="烹饪"),
    dict(question="野生蘑菇怎么清洗?", answer="菌褶朝下,用软毛刷轻轻刷掉泥土和落叶,检查菌褶里有没有虫子,切掉带土的菌柄基部,再用干布擦拭。当天采当天做,别泡在水里过夜。", category="烹饪"),
    dict(question="羊肚菌的空腔里藏了东西怎么洗?", answer="羊肚菌(Morchella esculenta)蜂窝状的空腔常藏泥土和虫,纵切两半或横切检查,用淡盐水轻轻漂洗,再用厨房纸吸干。洗后尽快下锅,彻底煎炒,既干净又安全。", category="烹饪"),
    dict(question="哪些蘑菇必须彻底做熟才能吃?", answer="羊肚菌、蜜环菌(Armillaria mellea)、紫丁香蘑含热敏刺激物,生吃或半生吃会恶心呕吐,必须彻底做熟;栽培的金针菇、双孢蘑菇则生食安全。野生菌一律做熟是最稳妥的原则。", category="烹饪"),
    dict(question="鲜蘑菇怎么储存?", answer="装纸袋或盖厨房纸放进冰箱冷藏,不要用塑料袋闷着,三四天内吃完。纸袋能吸潮防霉,塑料袋积水会加速变质。吃多少买多少,别囤太久。", category="烹饪"),
    dict(question="蘑菇能冷冻保存吗?", answer="能,但做熟后再冻比生冻更好,风味和口感损失小。生蘑菇冻后会出水变软,只适合做汤炖菜。冻好的熟蘑菇密封分装,吃时加热即可,能存好几个月。", category="烹饪"),
    dict(question="蘑菇怎么干燥保存?", answer="平菇、香菇(Lentinula edodes)、羊肚菌、黑喇叭菌都适合干燥:切片或整朵摊开,自然风干、晒干或用烘干机低温烘至脆硬,密封防潮可存一年。泡发的水是浓缩的高汤。", category="烹饪"),
    dict(question="鸡油菌下锅为什么全是水?", answer="蘑菇九成是水,鸡油菌(Cantharellus cibarius)一遇热就大量出水。正确做法是宽锅大火快炒,不盖盖子,先把水分蒸发掉再放黄油和调料,才能煎出金黄色和浓郁香气。", category="烹饪"),
    dict(question="香菇做菜前一定要煮熟吗?", answer="要。香菇(Lentinula edodes)彻底煮熟不仅能去除可能引起皮炎的刺激物,风味也更饱满。炖汤、炒菜、烧烤都行,就是别贪嫩夹生,香菇类菜肴一律做熟上桌。", category="烹饪"),
    dict(question="松露该怎么用?", answer="松露(Tuber spp.)几乎不加热,吃前用专用刨刀削成薄片,撒在刚出锅的意面、炒蛋或烩饭上,靠余温激发出香气。高温会毁掉松露的芬芳,几克就能香一整盘。", category="烹饪"),
]
